def main():
    import sympy as s
    root = Path(__file__).resolve().parents[1]
    checks = []
    def check(label, ok):
        checks.append(bool(ok))
        print(f"[{'PASS' if ok else 'FAIL'}] {label}")
    binding = json.loads((root / 'outputs/faster_three_site_2026_10_17/landing/PROOF_INPUT_BINDING.json').read_text())
    check('historical proof pins retain exact bytes', all(hashlib.sha256((root / row['path']).read_bytes()).hexdigest() == row['sha256'] for row in binding['pins']))

    # A finite complex-symmetric endpoint model; not the full physical apparatus.
    E = s.symbols('E', real=True)
    j = s.Rational(2, 3)
    H = s.Matrix([[1, s.Rational(1, 4)], [s.Rational(1, 4), -2]])
    Vp = s.Matrix([1, 0]); Vo = s.Matrix([0, 1])
    q = s.I + E**2 / 5
    M = E*s.eye(2)-H+j*q*(Vo*Vo.T)
    R = M.inv(); F = R*Vp; Fo = Vo.T*F
    direct = s.diff((Vp.T*R*Vp)[0], E)
    compressed = -(F.T*F)[0]-j*s.diff(q,E)*(Fo.T*Fo)[0]
    check('endpoint transpose compression equals directly differentiated inverse', s.cancel(direct-compressed)==0)
    wrong = -(F.conjugate().T*F)[0]-j*s.diff(q,E)*(Fo.conjugate().T*Fo)[0]
    check('literal transpose cannot be replaced by adjoint', s.simplify((direct-wrong).subs(E,0))!=0)

    x, lam, jj = s.symbols('x lam j', positive=True, real=True)
    m = x/(2*jj**2)-s.I*s.sqrt(1-x*x/(4*jj**2))/jj
    p2=x*x-lam*lam/3; kap2=3*jj*lam
    determinant=p2*(x-kap2*m)-8*lam*lam*x/3
    coherent=(x+s.I*lam)**3-kap2*p2*(m+s.I/jj)
    check('exact finite-band cubic decomposition with physical Weyl load', s.expand(determinant-coherent)==0)
    derivative=3*(x+s.I*lam)**2-kap2*(2*x*(m+s.I/jj)+p2*s.diff(m,x))
    check('differentiated cubic cancellation retains Weyl derivative', s.simplify(s.diff(determinant,x)-derivative)==0)
    check('finite-band correction is not identically a Markov cubic', s.simplify((determinant-(x+s.I*lam)**3).subs({x:s.Rational(1,2),lam:s.Rational(1,10),jj:1}))!=0)

    # The component ceilings are supplied analytical premises, not proved here.
    with localcontext() as ctx:
        ctx.prec=60
        D=Decimal
        lam=D('1e-12'); g=D('5e-8'); T=D('2e13'); M=D(5000000)
        total=sum(D(v) for v in ('1.3e-8','.0000231','.000610','.000216','.0000031','1e-10','1e-10'))
        check('complete ceiling sum at faster nominal point', total==D('.0008522132') and total<D('.00086'))
        check('lambda T and finite-cut scale belong to faster point',lam*T==20 and 4*g*T==4000000)
        check('finite-cut exponent from conservative sinh ceiling',-M+4*g*T*D('1.176')==D(-296000))
        check('resource counts and failure-effect ceiling',M+243==5000243 and 2*M+281==10000281 and D('.00086')**2==D('7.396e-7'))
        check('endpoint derivative coefficient enclosure',D('.003')*D(3270)**2/D('1.93')<16622)
        check('selected derivative correction throughout stated source domain',3+D('4.509')*D('1e-8')/D('.0027')<D('3.00002'))
    print('Scope: finite endpoint identity, exact cubic algebra and ceiling arithmetic only. Full physical recovery, contour/time bounds, inherited premises and complete dynamics are analytical obligations; hashes establish identity, not proof.')
    print(f'TOTAL: PASS={sum(checks)} FAIL={len(checks)-sum(checks)}')
    return 0 if all(checks) else 1


if __name__ == '__main__':
    raise SystemExit(main())
